//! Evaluator against pycocotools' COCOeval on the seeded scenarios in `tests/fixtures/coco/` (generated by
//! `bench/parity/coco_reference.py`; see that script for how the inputs are made exact in f32). Run with
//! `--nocapture` to print the parity table.

use folo_vision::metrics::{EvalConfig, EvalReport, Evaluator, Truth};
use folo_vision::{Detection, Xyxy};
use serde_json::Value;
use std::path::Path;

/// The report's values are f32: rounding a value in `[0, 1]` from the f64 maths (which agrees with pycocotools to
/// ~1e-16) costs at most half an f32 ulp, `2^-25 ≈ 3e-8`. So anything above 1e-7 is a real difference.
const TOL: f64 = 1e-7;

struct Fixture {
    name: String,
    num_classes: usize,
    coco_compatible_only: bool,
    images: Vec<(Vec<Detection>, Vec<Truth>)>,
    coco: Value,
}

fn f32_of(v: &Value) -> f32 {
    v.as_f64().expect("number") as f32
}

fn load(path: &Path) -> Fixture {
    let v: Value = serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap();
    let bbox =
        |b: &[Value]| Xyxy { x1: f32_of(&b[0]), y1: f32_of(&b[1]), x2: f32_of(&b[2]), y2: f32_of(&b[3]) };
    let images = v["images"]
        .as_array()
        .unwrap()
        .iter()
        .map(|im| {
            let preds = im["preds"]
                .as_array()
                .unwrap()
                .iter()
                .map(|p| {
                    let p = p.as_array().unwrap();
                    Detection { bbox: bbox(p), score: f32_of(&p[4]), class: p[5].as_u64().unwrap() as u32 }
                })
                .collect();
            let truths = im["truths"]
                .as_array()
                .unwrap()
                .iter()
                .map(|t| {
                    let t = t.as_array().unwrap();
                    Truth { bbox: bbox(t), class: t[4].as_u64().unwrap() as u32 }
                })
                .collect();
            (preds, truths)
        })
        .collect();
    Fixture {
        name: v["name"].as_str().unwrap().to_owned(),
        num_classes: v["num_classes"].as_u64().unwrap() as usize,
        coco_compatible_only: v["coco_compatible_only"].as_bool().unwrap(),
        images,
        coco: v["coco"].clone(),
    }
}

fn fixtures() -> Vec<Fixture> {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/coco");
    let mut paths: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(paths.len() >= 20, "expected the generated fixtures in {}", dir.display());
    paths.iter().map(|p| load(p)).collect()
}

fn evaluate(fx: &Fixture, cfg: EvalConfig) -> EvalReport {
    let mut ev = Evaluator::with_config(fx.num_classes, cfg);
    for (preds, truths) in &fx.images {
        ev.add_image(preds, truths);
    }
    ev.compute()
}

/// Largest absolute difference between the report and pycocotools over mAP50-95, mAP50, mAP per IoU threshold and
/// every class's AP per threshold, AP50 and AP50-95; `Err` when the evaluated class sets differ.
fn max_diff(r: &EvalReport, coco: &Value) -> Result<f64, String> {
    let num = |v: &Value| v.as_f64().unwrap();
    let want_classes: Vec<u32> =
        coco["per_class"].as_array().unwrap().iter().map(|c| c["class"].as_u64().unwrap() as u32).collect();
    let got_classes: Vec<u32> = r.per_class.iter().map(|c| c.class).collect();
    if want_classes != got_classes {
        return Err(format!("evaluated classes: FOLO {got_classes:?}, pycocotools {want_classes:?}"));
    }
    if want_classes.is_empty() {
        // pycocotools: every stat -1. FOLO: nothing to average, so 0 and an empty per_class.
        assert_eq!(num(&coco["map50_95"]), -1.0);
        return Ok(f64::from(r.map50_95.abs().max(r.map50.abs())));
    }
    let mut d = 0.0f64;
    let mut upd = |got: f32, want: &Value| d = d.max((f64::from(got) - num(want)).abs());
    upd(r.map50_95, &coco["map50_95"]);
    upd(r.map50, &coco["map50"]);
    upd(r.map50_95, &coco["stats"][0]);
    upd(r.map50, &coco["stats"][1]);
    upd(r.map_per_iou[5], &coco["stats"][2]);
    for (t, want) in coco["map_per_iou"].as_array().unwrap().iter().enumerate() {
        upd(r.map_per_iou[t], want);
    }
    for (c, want) in r.per_class.iter().zip(coco["per_class"].as_array().unwrap()) {
        upd(c.map50_95, &want["ap50_95"]);
        upd(c.map50, &want["ap50"]);
        for (t, w) in want["ap"].as_array().unwrap().iter().enumerate() {
            upd(c.ap[t], w);
        }
    }
    Ok(d)
}

/// Every fixture matches pycocotools with `EvalConfig::coco()`, and with the defaults except where a fixture is marked
/// `coco_compatible_only` (boxes outside COCO's area range), where the default must differ.
#[test]
fn matches_pycocotools() {
    let mut failures = Vec::new();
    let show = |d: &Result<f64, String>| match d {
        Ok(d) => format!("{d:.1e}"),
        Err(_) => "classes".to_owned(),
    };
    println!(
        "| {:22} | {:>9} | {:>9} | {:>9} | {:>9} | {:>11} | {:>9} |",
        "scenario", "COCO AP", "COCO AP50", "FOLO AP", "FOLO AP50", "default |Δ|", "coco |Δ|"
    );
    for fx in fixtures() {
        let default = evaluate(&fx, EvalConfig::default());
        let coco = evaluate(&fx, EvalConfig::coco());
        let (d_default, d_coco) = (max_diff(&default, &fx.coco), max_diff(&coco, &fx.coco));
        println!(
            "| {:22} | {:9.6} | {:9.6} | {:9.6} | {:9.6} | {:>11} | {:>9} |",
            fx.name,
            fx.coco["map50_95"].as_f64().unwrap(),
            fx.coco["map50"].as_f64().unwrap(),
            coco.map50_95,
            coco.map50,
            show(&d_default),
            show(&d_coco),
        );
        match d_coco {
            Ok(d) if d <= TOL => {}
            Ok(d) => failures.push(format!("{}: coco_compatible differs by {d:e}", fx.name)),
            Err(e) => failures.push(format!("{}: coco_compatible: {e}", fx.name)),
        }
        match (fx.coco_compatible_only, d_default) {
            (false, Ok(d)) if d <= TOL => {
                assert_eq!(default, coco, "{}: modes differ inside the area range", fx.name)
            }
            (false, Ok(d)) => failures.push(format!("{}: default differs by {d:e}", fx.name)),
            (false, Err(e)) => failures.push(format!("{}: default: {e}", fx.name)),
            (true, Ok(d)) if d <= TOL => {
                failures.push(format!("{}: expected the default to differ", fx.name))
            }
            (true, _) => {}
        }
    }
    assert!(failures.is_empty(), "{failures:#?}");
}

/// Splitting the images across evaluators and merging gives the same report (so the parity holds for parallel
/// evaluation too), in both modes.
#[test]
fn merged_evaluators_match() {
    for fx in fixtures() {
        for cfg in [EvalConfig::default(), EvalConfig::coco()] {
            let whole = evaluate(&fx, cfg.clone());
            let mut parts: Vec<Evaluator> =
                (0..3).map(|_| Evaluator::with_config(fx.num_classes, cfg.clone())).collect();
            let chunk = fx.images.len().div_ceil(3);
            for (i, (preds, truths)) in fx.images.iter().enumerate() {
                parts[i / chunk].add_image(preds, truths);
            }
            let mut it = parts.into_iter();
            let mut merged = it.next().unwrap();
            it.for_each(|p| merged.merge(p));
            assert_eq!(merged.compute(), whole, "{}", fx.name);
        }
    }
}
